import { Component, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { WebsocketService } from '../../services/websocket.service';
import { AuthService } from '../../services/auth.service';
import { Auction, BidUpdate } from '../../models/auction.model';

interface ToastMessage {
  type: 'success' | 'danger' | 'info' | 'warning';
  text: string;
  id: number;
}

@Component({
  selector: 'app-auction-detail',
  templateUrl: './auction-detail.component.html',
  styleUrls: ['./auction-detail.component.css']
})
export class AuctionDetailComponent implements OnInit, OnDestroy {
  auction: Auction | null = null;
  auctionId!: number;
  currentBid = 0;
  highestBidder: string | null = null;
  auctionStatus = '';
  bidAmount: number | null = null;
  isConnected = false;
  isSubmitting = false;
  toasts: ToastMessage[] = [];
  private toastCounter = 0;
  bidHistory: { amount: number; bidder: string; time: Date }[] = [];

  private wsSub!: Subscription;
  private statusSub!: Subscription;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private wsService: WebsocketService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    this.auctionId = Number(this.route.snapshot.paramMap.get('id'));

    const state = history.state as { auction?: Auction };
    if (state?.auction) {
      this.auction = state.auction;
      this.currentBid = this.auction.currentBid;
      this.highestBidder = this.auction.highestBidder;
      this.auctionStatus = this.auction.status;
    }

    this.connectWebSocket();
  }

  private connectWebSocket(): void {
    this.wsService.connect();

    this.statusSub = this.wsService.connectionStatus$.subscribe(status => {
      this.isConnected = status === 'CONNECTED';
      if (status === 'ERROR') {
        this.showToast('danger', 'WebSocket connection failed. Real-time updates unavailable.');
      }
    });

    this.wsSub = this.wsService.messages$.subscribe((msg: BidUpdate) => {
      if (msg.type === 'ERROR') {
        this.showToast('danger', msg.message || 'An error occurred.');
        this.isSubmitting = false;
        return;
      }

      if (msg.type === 'AUCTION_STARTED') {
        this.auctionStatus = 'LIVE';
        this.showToast('success', 'Auction has started! Place your bids now.');
        return;
      }

      if (msg.type === 'AUCTION_STOPPED') {
        this.auctionStatus = 'ENDED';
        this.showToast('info', 'Auction has ended.');
        return;
      }

      // Regular bid update
      if (msg.auctionId === this.auctionId || !msg.auctionId) {
        if (msg.amount !== undefined && msg.amount > this.currentBid) {
          const prevBidder = this.highestBidder;
          this.currentBid = msg.amount;
          this.highestBidder = msg.highestBidder || (msg.bidderId?.toString() ?? null);

          this.bidHistory.unshift({
            amount: msg.amount,
            bidder: this.highestBidder ?? 'Unknown',
            time: new Date()
          });

          const myId = this.authService.getUserId();
          if (myId && msg.bidderId === myId) {
            this.showToast('success', `Your bid of ${this.formatCurrency(msg.amount)} is now the highest!`);
          } else if (prevBidder) {
            this.showToast('info', `New highest bid: ${this.formatCurrency(msg.amount)}`);
          }
        }
        this.isSubmitting = false;
      }
    });
  }

  placeBid(): void {
    if (!this.bidAmount || this.bidAmount <= this.currentBid) {
      this.showToast('warning', `Bid must be greater than current bid of ${this.formatCurrency(this.currentBid)}.`);
      return;
    }

    const userId = this.authService.getUserId();
    if (!userId) {
      this.showToast('danger', 'User ID not found. Please set your User ID in Wallet settings.');
      return;
    }

    this.isSubmitting = true;
    this.wsService.sendBid({
      auctionId: this.auctionId,
      bidderId: userId,
      amount: this.bidAmount
    });

    this.bidAmount = null;
  }

  showToast(type: ToastMessage['type'], text: string): void {
    const id = ++this.toastCounter;
    this.toasts.push({ type, text, id });
    setTimeout(() => {
      this.toasts = this.toasts.filter(t => t.id !== id);
    }, 5000);
  }

  dismissToast(id: number): void {
    this.toasts = this.toasts.filter(t => t.id !== id);
  }

  formatCurrency(amount: number): string {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(amount);
  }

  goBack(): void {
    void this.router.navigate(['/home']);
  }

  ngOnDestroy(): void {
    this.wsService.disconnect();
    if (this.wsSub) this.wsSub.unsubscribe();
    if (this.statusSub) this.statusSub.unsubscribe();
  }
}
<!-- Toast Container -->
<div class="toast-container">
  <div
    *ngFor="let toast of toasts"
    class="toast show align-items-center border-0 mb-2"
    [ngClass]="{
      'text-bg-success': toast.type === 'success',
      'text-bg-danger': toast.type === 'danger',
      'text-bg-info': toast.type === 'info',
      'text-bg-warning': toast.type === 'warning'
    }"
    role="alert">
    <div class="d-flex">
      <div class="toast-body">
        <i class="bi me-2"
           [ngClass]="{
             'bi-check-circle-fill': toast.type === 'success',
             'bi-x-circle-fill': toast.type === 'danger',
             'bi-info-circle-fill': toast.type === 'info',
             'bi-exclamation-triangle-fill': toast.type === 'warning'
           }"></i>
        {{ toast.text }}
      </div>
      <button type="button" class="btn-close btn-close-white me-2 m-auto" (click)="dismissToast(toast.id)"></button>
    </div>
  </div>
</div>

<div class="page-wrapper">
  <div class="container">
    <!-- Back Button -->
    <button class="btn btn-outline-secondary btn-sm mb-3" (click)="goBack()">
      <i class="bi bi-arrow-left me-1"></i>Back to Home
    </button>

    <div class="row g-4">
      <!-- Left: Product Info -->
      <div class="col-lg-7">
        <div class="card h-100">
          <div *ngIf="auction">
            <!-- Product Image -->
            <img
              [src]="auction.product.imageUrl || 'https://via.placeholder.com/700x350?text=No+Image'"
              class="card-img-top rounded-top"
              [alt]="auction.product.productName"
              style="height: 320px; object-fit: cover;"
              (error)="$any($event.target).src = 'https://via.placeholder.com/700x350?text=No+Image'"
            />

            <div class="card-body">
              <!-- Status + Category -->
              <div class="d-flex gap-2 mb-3">
                <span class="badge px-3 py-2"
                      [ngClass]="{
                        'bg-danger': auctionStatus === 'LIVE',
                        'bg-primary': auctionStatus === 'CREATED',
                        'bg-secondary': auctionStatus === 'ENDED'
                      }">
                  <i class="bi bi-circle-fill me-1 small" *ngIf="auctionStatus === 'LIVE'"></i>
                  {{ auctionStatus }}
                </span>
                <span class="badge bg-light text-dark px-3 py-2">
                  {{ auction.product.category.categoryName }}
                </span>
              </div>

              <h3 class="fw-bold mb-2">{{ auction.product.productName }}</h3>
              <p class="text-muted">{{ auction.product.description }}</p>

              <hr />

              <div class="row text-center g-3">
                <div class="col-6">
                  <p class="text-muted small mb-1">Starting Price</p>
                  <p class="fw-bold text-secondary">{{ formatCurrency(auction.product.startingPrice) }}</p>
                </div>
                <div class="col-6">
                  <p class="text-muted small mb-1">Seller</p>
                  <p class="fw-bold text-secondary">{{ auction.product.seller.name }}</p>
                </div>
              </div>
            </div>
          </div>

          <div class="card-body text-center text-muted" *ngIf="!auction">
            <i class="bi bi-search display-4"></i>
            <p class="mt-3">No auction information available. Please go back and select an auction.</p>
          </div>
        </div>
      </div>

      <!-- Right: Bidding Panel -->
      <div class="col-lg-5">
        <!-- Connection Status -->
        <div class="alert mb-3 py-2 d-flex align-items-center gap-2"
             [ngClass]="isConnected ? 'alert-success' : 'alert-secondary'">
          <span class="badge rounded-pill"
                [ngClass]="isConnected ? 'bg-success' : 'bg-secondary'">
            <i class="bi bi-wifi me-1"></i>{{ isConnected ? 'Live' : 'Offline' }}
          </span>
          {{ isConnected ? 'Real-time bidding active' : 'Connecting to auction server...' }}
        </div>

        <!-- Current Bid Panel -->
        <div class="bid-panel mb-4">
          <p class="text-muted small mb-1 text-uppercase fw-semibold tracking-wide">Current Highest Bid</p>
          <div class="bid-amount mb-1">{{ formatCurrency(currentBid) }}</div>
          <p class="text-muted small" *ngIf="highestBidder">
            <i class="bi bi-person-fill me-1"></i>
            Leader: <strong>{{ highestBidder }}</strong>
          </p>
          <p class="text-muted small" *ngIf="!highestBidder">
            <i class="bi bi-person-slash me-1"></i>No bids yet — be the first!
          </p>
        </div>

        <!-- Place Bid -->
        <div class="card mb-4" *ngIf="auctionStatus === 'LIVE'">
          <div class="card-body">
            <h6 class="card-title fw-bold mb-3">
              <i class="bi bi-lightning-fill text-warning me-2"></i>Place Your Bid
            </h6>
            <div class="input-group mb-3">
              <span class="input-group-text fw-bold">&#x20B9;</span>
              <input
                type="number"
                class="form-control"
                placeholder="Enter bid amount"
                [(ngModel)]="bidAmount"
                [min]="currentBid + 1"
                [disabled]="isSubmitting"
              />
            </div>
            <p class="text-muted small mb-3">
              Minimum bid: <strong>{{ formatCurrency(currentBid + 1) }}</strong>
            </p>
            <button
              class="btn btn-accent w-100 fw-bold py-2"
              (click)="placeBid()"
              [disabled]="isSubmitting || !bidAmount">
              <span *ngIf="isSubmitting" class="spinner-border spinner-border-sm me-2"></span>
              <i *ngIf="!isSubmitting" class="bi bi-hammer me-2"></i>
              {{ isSubmitting ? 'Placing Bid...' : 'Place Bid' }}
            </button>
          </div>
        </div>

        <!-- Auction Not Live -->
        <div class="alert alert-info" *ngIf="auctionStatus === 'CREATED'">
          <i class="bi bi-clock me-2"></i>
          <strong>Auction not started yet.</strong> Wait for the admin to start this auction.
        </div>

        <div class="alert alert-secondary" *ngIf="auctionStatus === 'ENDED'">
          <i class="bi bi-flag-fill me-2"></i>
          <strong>Auction has ended.</strong>
          <span *ngIf="highestBidder"> Winner: <strong>{{ highestBidder }}</strong></span>
        </div>

        <!-- Bid History -->
        <div class="card" *ngIf="bidHistory.length > 0">
          <div class="card-header bg-white fw-semibold">
            <i class="bi bi-clock-history me-2"></i>Recent Bids
          </div>
          <ul class="list-group list-group-flush">
            <li class="list-group-item py-2" *ngFor="let bid of bidHistory.slice(0, 5)">
              <div class="d-flex justify-content-between align-items-center">
                <div>
                  <i class="bi bi-person-circle me-1 text-muted"></i>
                  <span class="fw-semibold">{{ bid.bidder }}</span>
                </div>
                <div class="text-end">
                  <span class="fw-bold text-primary">{{ formatCurrency(bid.amount) }}</span>
                  <br/>
                  <small class="text-muted">{{ bid.time | date:'HH:mm:ss' }}</small>
                </div>
              </div>
            </li>
          </ul>
        </div>
      </div>
    </div>
  </div>
</div>
